<?php
namespace App\Http\Controllers\Tenant\Admin;use App\Http\Controllers\Controller;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\Inertia;use Inertia\Response;
class NotificationController extends Controller{public function index(Request $r):Response{$u=$r->user('tenant');return Inertia::render('Tenant/Admin/Notifications/Index',['notifications'=>DB::table('notifications')->where('notifiable_type',$u::class)->where('notifiable_id',$u->id)->latest()->paginate(50),'preferences'=>DB::table('notification_preferences')->where('user_id',$u->id)->get()->keyBy('event')]);}public function read(Request $r,string $id):RedirectResponse{$u=$r->user('tenant');DB::table('notifications')->where('id',$id)->where('notifiable_type',$u::class)->where('notifiable_id',$u->id)->update(['read_at'=>now(),'updated_at'=>now()]);return back();}public function readAll(Request $r):RedirectResponse{$u=$r->user('tenant');DB::table('notifications')->where('notifiable_type',$u::class)->where('notifiable_id',$u->id)->whereNull('read_at')->update(['read_at'=>now(),'updated_at'=>now()]);return back()->with('status','All notifications marked read.');}public function preference(Request $r):RedirectResponse{$u=$r->user('tenant');$d=$r->validate(['event'=>['required','in:assignment,mention,sla_escalation,ticket_update,conversation_reply,ai.approval_requested'],'in_app'=>['required','boolean'],'email'=>['required','boolean'],'browser'=>['required','boolean']]);DB::table('notification_preferences')->updateOrInsert(['user_id'=>$u->id,'event'=>$d['event']],array_merge($d,['created_at'=>now(),'updated_at'=>now()]));return back()->with('status','Notification preference saved.');}}
